import { D1ProvenanceCommitRepository } from '../../src/provenance-repositories.js'
import { ProvenanceRegistrationServiceV2, ProvenanceVerificationServiceV2 } from '../../src/provenance-core.generated.js'
export default{async fetch(request,env){const body=await request.json(),repository=new D1ProvenanceCommitRepository(env.PROVENANCE_D1);try{if(body.action==='verify')return Response.json(await new ProvenanceVerificationServiceV2({repository,receiptKeys:body.receiptKeys}).verify(body.request));if(body.action==='get')return Response.json(await repository.getRecordById(body.recordId));return Response.json(await new ProvenanceRegistrationServiceV2({repository,captureKeys:body.captureKeys,receiptKeys:body.receiptKeys}).register(body.subject,body.request))}catch(error){return Response.json({ok:false,code:error.code},{status:error.status||500})}}}
